def count_islands(grid):
    """Count 4-connected groups of 1s in a grid of 0/1 lists."""
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def in_bounds(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def bfs(start):
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if in_bounds(nr, nc) and grid[nr][nc] == 1:
                    grid[nr][nc] = 0
                    stack.append((nr, nc))

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                grid[r][c] = 0
                bfs((r, c))
                count += 1

    return count
